{
  "name": "rf_get_ready_status",
  "confidence": "medium",
  "docstring": "Returns the RF/PHY ready status code, inspecting pending status messages and the RX queue, flushing stale RX data, and refreshing channel information when necessary.",
  "subsystem": "rf",
  "var_renames": {
    "v0": "rf_ctx",
    "result": "front_status",
    "v2": "rx_flush_status"
  },
  "struct_hints": [
    {
      "offset": 24,
      "meaning": "RF status/message list head or pending-message pointer; nonzero indicates an entry is available"
    },
    {
      "offset": 32,
      "meaning": "ready/force-complete or abort flag that short-circuits the status query"
    },
    {
      "offset": 26,
      "meaning": "status/message ID byte in a popped RF status list entry"
    }
  ]
}
